import React from 'react';
import axios from 'axios';
import { toast } from 'react-toastify';

export default function InstructorCurriculumEditor({ course, setCourse }) {

  // --- Logic Helpers ---

  const addModule = () => {
    const newModule = { title: '', content: [] };
    setCourse({ ...course, modules: [...(course.modules || []), newModule] });
  };

  const addItem = (mIdx, type) => {
    const newModules = [...course.modules];
    const newItem = type === 'video' 
      ? { type: 'video', title: '', videoUrl: '', uploadType: 'url' }
      : { type: 'quiz', title: '', questions: [{ questionText: '', options: ['', '', '', ''], correctAnswer: 0 }] };

    newModules[mIdx].content.push(newItem);
    setCourse({ ...course, modules: newModules });
  };

  const updateItem = (mIdx, iIdx, updates) => {
    const newModules = [...course.modules];
    newModules[mIdx].content[iIdx] = { ...newModules[mIdx].content[iIdx], ...updates };
    setCourse({ ...course, modules: newModules });
  };

  const addQuestion = (mIdx, iIdx) => {
    const newModules = [...course.modules];
    const newQuestion = { questionText: '', options: ['', '', '', ''], correctAnswer: 0 };
    newModules[mIdx].content[iIdx].questions.push(newQuestion);
    setCourse({ ...course, modules: newModules });
  };

  const updateQuestion = (mIdx, iIdx, qIdx, updates) => {
    const newModules = [...course.modules];
    const item = newModules[mIdx].content[iIdx];
    item.questions[qIdx] = { ...item.questions[qIdx], ...updates };
    setCourse({ ...course, modules: newModules });
  };

  const handleLocalVideoUpload = async (mIdx, iIdx, file) => {
    if (!file) return;

    const formData = new FormData();
    formData.append('video', file);

    updateItem(mIdx, iIdx, { isUploading: true });

    try {
      // Replace with your actual backend upload endpoint
      const { data } = await axios.post('/api/upload/video', formData, {
        headers: { 'Content-Type': 'multipart/form-data' }
      });
      updateItem(mIdx, iIdx, { videoUrl: data.url, uploadType: 'local', isUploading: false });
      toast.success("Video uploaded successfully!");
    } catch (err) {
      updateItem(mIdx, iIdx, { isUploading: false });
      toast.error("Upload failed");
    }
  };

  return (
    <div className="curriculum-editor" style={{ padding: '20px', color: '#fff' }}>
      <h2 style={{ marginBottom: 20 }}>Course Curriculum</h2>

      {course.modules?.map((module, mIdx) => (
        <div key={mIdx} className="glass" style={{ padding: 25, marginBottom: 20, borderRadius: 15, border: '1px solid rgba(124,58,237,0.3)' }}>
          <input 
            className="input" 
            style={{ fontSize: 20, fontWeight: 700, marginBottom: 15, background: 'rgba(255,255,255,0.05)' }}
            placeholder="Module Title (e.g. Introduction to Python)"
            value={module.title}
            onChange={(e) => {
              const newModules = [...course.modules];
              newModules[mIdx].title = e.target.value;
              setCourse({ ...course, modules: newModules });
            }}
          />

          <div className="items-list" style={{ marginLeft: 20 }}>
            {module.content?.map((item, iIdx) => (
              <div key={iIdx} style={{ background: 'rgba(0,0,0,0.2)', padding: 20, borderRadius: 12, marginBottom: 15, borderLeft: `4px solid ${item.type === 'video' ? '#00f5d4' : '#f72585'}` }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 10 }}>
                  <span style={{ fontSize: 12, fontWeight: 800, textTransform: 'uppercase', color: item.type === 'video' ? '#00f5d4' : '#f72585' }}>
                    {item.type}
                  </span>
                </div>

                <input 
                  className="input" 
                  placeholder={`${item.type === 'video' ? 'Video' : 'Quiz'} Title`}
                  value={item.title}
                  onChange={(e) => updateItem(mIdx, iIdx, { title: e.target.value })}
                />

                {/* --- VIDEO SPECIFIC --- */}
                {item.type === 'video' && (
                  <div style={{ marginTop: 15 }}>
                    <div style={{ display: 'flex', gap: 10, flexDirection: 'column' }}>
                      <label style={{ fontSize: 12, color: '#6b6490' }}>YouTube URL:</label>
                      <input 
                        className="input-sm" 
                        placeholder="https://youtube.com/watch?v=..."
                        value={item.videoUrl}
                        onChange={(e) => updateItem(mIdx, iIdx, { videoUrl: e.target.value, uploadType: 'url' })}
                      />
                      <div style={{ textAlign: 'center', margin: '5px 0', fontSize: 12, color: '#6b6490' }}>— OR UPLOAD FROM PC —</div>
                      <input 
                        type="file" 
                        accept="video/*" 
                        style={{ fontSize: 12 }}
                        onChange={(e) => handleLocalVideoUpload(mIdx, iIdx, e.target.files[0])}
                      />
                      {item.isUploading && <div className="loader-sm" style={{ color: '#00f5d4' }}>Uploading to server...</div>}
                    </div>
                  </div>
                )}

                {/* --- QUIZ SPECIFIC (Google Forms Style) --- */}
                {item.type === 'quiz' && (
                  <div style={{ marginTop: 20, borderTop: '1px solid rgba(255,255,255,0.1)', paddingTop: 15 }}>
                    <h4 style={{ marginBottom: 15, fontSize: 14 }}>Quiz Questions</h4>
                    {item.questions.map((q, qIdx) => (
                      <div key={qIdx} style={{ background: 'rgba(255,255,255,0.03)', padding: 15, borderRadius: 8, marginBottom: 15 }}>
                        <input 
                          className="input" 
                          placeholder={`Question ${qIdx + 1}`}
                          value={q.questionText}
                          onChange={(e) => updateQuestion(mIdx, iIdx, qIdx, { questionText: e.target.value })}
                          style={{ marginBottom: 10 }}
                        />
                        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10 }}>
                          {q.options.map((opt, oIdx) => (
                            <div key={oIdx} style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                              <input 
                                type="radio" 
                                name={`correct-${mIdx}-${iIdx}-${qIdx}`} 
                                checked={q.correctAnswer === oIdx}
                                onChange={() => updateQuestion(mIdx, iIdx, qIdx, { correctAnswer: oIdx })}
                              />
                              <input 
                                className="input-sm" 
                                placeholder={`Option ${oIdx + 1}`}
                                value={opt}
                                onChange={(e) => {
                                  const newOpts = [...q.options];
                                  newOpts[oIdx] = e.target.value;
                                  updateQuestion(mIdx, iIdx, qIdx, { options: newOpts });
                                }}
                              />
                            </div>
                          ))}
                        </div>
                      </div>
                    ))}
                    <button 
                      className="btn-sm" 
                      style={{ background: 'rgba(255,255,255,0.1)', color: '#fff', border: '1px dashed #6b6490' }}
                      onClick={() => addQuestion(mIdx, iIdx)}
                    >
                      + Add Question
                    </button>
                  </div>
                )}
              </div>
            ))}
          </div>

          <div style={{ display: 'flex', gap: 10, marginTop: 15 }}>
            <button className="btn-sm" onClick={() => addItem(mIdx, 'video')}>+ Add Video</button>
            <button className="btn-sm" onClick={() => addItem(mIdx, 'quiz')}>+ Add Quiz</button>
          </div>
        </div>
      ))}

      <button className="btn" style={{ width: '100%', marginTop: 20 }} onClick={addModule}>
        + Add New Module
      </button>
    </div>
  );
}
